select ci.content_key, md5(civ.stem||'|'||string_agg(c.choice_key||':'||c.choice_text||':'||c.is_correct::text||':'||c.rationale,'|' order by c.choice_key)) h from app.content_items ci join app.content_item_versions civ on civ.content_item_id=ci.id join app.mcq_choices c on c.content_item_version_id=civ.id where ci.exam_pack_version_id='2d88ba5e-a6a3-43b8-bfae-9e5505a178a7' and ci.content_key like 'APBIO-MCQ-SV-%' group by ci.content_key, civ.stem order by 1;